let parsedOutput;
try {
  // Extract JSON from markdown code blocks
  let jsonString = aiOutput.output.trim();

  // Remove markdown code block markers if present
  if (jsonString.startsWith('```json')) {
    jsonString = jsonString.replace(/^```json\n?/, '');
  }
  if (jsonString.startsWith('```')) {
    jsonString = jsonString.replace(/^```\n?/, '');
  }
  if (jsonString.endsWith('```')) {
    jsonString = jsonString.replace(/\n?```$/, '');
  }

  // Clean up the JSON string - remove extra newlines and spaces
  jsonString = jsonString.replace(/\n\s*/g, '').trim();

  // Parse the cleaned JSON
  parsedOutput = JSON.parse(jsonString);

} catch (error) {
  console.error("Raw AI output:", aiOutput.output);
  console.error("Parsing error:", error.message);
  throw new Error(`Failed to parse AI Agent output: ${error.message}`);
}

// Validate required fields for the new format
const requiredFields = ['decision', 'threat_level', 'analysis', 'survival_timeline', 'notification_message', 'reasoning'];
const missingFields = requiredFields.filter(field => !(field in parsedOutput));

if (missingFields.length > 0) {
  throw new Error(`Missing required fields in AI output: ${missingFields.join(', ')}`);
}

// Validate field types
if (!['EMERGENCY_HEALING', 'NOTIFY_ONLY'].includes(parsedOutput.decision)) {
  throw new Error(`Invalid decision value: ${parsedOutput.decision}. Must be EMERGENCY_HEALING or NOTIFY_ONLY`);
}

if (!['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'].includes(parsedOutput.threat_level)) {
  throw new Error(`Invalid threat_level value: ${parsedOutput.threat_level}. Must be LOW, MEDIUM, HIGH, or CRITICAL`);
}

if (typeof parsedOutput.analysis !== 'string' || parsedOutput.analysis.trim() === '') {
  throw new Error('Analysis must be a non-empty string');
}

// Ensure immediate_actions is an array
if (!Array.isArray(parsedOutput.immediate_actions)) {
  parsedOutput.immediate_actions = [];
}

// Return formatted JSON with all fields
return [
  {
    json: {
      decision: parsedOutput.decision,
      threat_level: parsedOutput.threat_level,
      instance: parsedOutput.instance,
      analysis: parsedOutput.analysis,
      immediate_actions: parsedOutput.immediate_actions,
      survival_timeline: parsedOutput.survival_timeline,
      notification_message: parsedOutput.notification_message,
      reasoning: parsedOutput.reasoning,

      // Add computed fields for convenience
      is_emergency: parsedOutput.decision === 'EMERGENCY_HEALING',
      is_critical: ['HIGH', 'CRITICAL'].includes(parsedOutput.threat_level),
      requires_action: parsedOutput.immediate_actions.length > 0,

      // Metadata
      parsed_at: new Date().toISOString(),
      ai_output_raw: aiOutput.output // Keep original for debugging
    }
  }
];

