// Fixed Dynamic SSH Command Executor - Handles AI markdown output
const inputData = $input.first().json;
const alertData = $node["Code"].json;

// Parse AI response from markdown format
let aiResponse;
try {
  // Check if we have raw AI output or parsed JSON
  if (inputData.output) {
    // Raw AI output with markdown - extract JSON
    let jsonString = inputData.output.trim();

    // Remove markdown code block markers
    if (jsonString.startsWith('```json')) {
      jsonString = jsonString.replace(/^```json\n?/, '');
    }
    if (jsonString.startsWith('```')) {
      jsonString = jsonString.replace(/^```\n?/, '');
    }
    if (jsonString.endsWith('```')) {
      jsonString = jsonString.replace(/\n?```$/, '');
    }

    // Clean and parse JSON
    jsonString = jsonString.replace(/\n\s*/g, '').trim();
    aiResponse = JSON.parse(jsonString);

  } else {
    // Already parsed JSON
    aiResponse = inputData;
  }
} catch (error) {
  console.error("Failed to parse AI response:", error.message);
  console.error("Raw input:", JSON.stringify(inputData, null, 2));

  return [{
    json: {
      execution_status: 'PARSE_ERROR',
      error: `Failed to parse AI response: ${error.message}`,
      raw_input: inputData,
      discord_message: '❌ Error parsing AI recommendations. Manual intervention required.'
    }
  }];
}

// Extract instance IP from alert data
const instanceIP = alertData.instance.split(':')[0];

// SSH Credential mapping
const credentialMap = {
  '47.129.163.27': 'SSH Cred - content-demo-server-2',
  // Add more servers as needed
};

const sshCredential = credentialMap[instanceIP];
if (!sshCredential) {
  return [{
    json: {
      execution_status: 'NO_CREDENTIAL',
      message: `No SSH credential configured for ${instanceIP}`,
      available_credentials: Object.keys(credentialMap),
      discord_message: `❌ No SSH access configured for server ${instanceIP}. Manual intervention required.`
    }
  }];
}

// Safety validation function
function validateCommand(command, riskLevel) {
  const dangerousPatterns = [
    'rm -rf /',
    'dd if=',
    'mkfs',
    'fdisk',
    'shutdown',
    'reboot',
    'halt',
    'chmod 777 /',
    '> /etc/',
    'format',
    'wipefs'
  ];

  const isDangerous = dangerousPatterns.some(pattern => 
    command.toLowerCase().includes(pattern.toLowerCase())
  );

  if (isDangerous) {
    return { safe: false, reason: `Blocked dangerous pattern in command: ${command}` };
  }

  // For this implementation, block RISKY commands
  if (riskLevel === 'RISKY') {
    return { safe: false, reason: `RISKY commands require manual approval: ${command}` };
  }

  return { safe: true, reason: 'Command passed safety checks' };
}

// Process targeted actions from AI response
const actionsToExecute = [];
const blockedActions = [];

console.log("Processing AI response:", JSON.stringify(aiResponse, null, 2));

if (aiResponse.targeted_actions && Array.isArray(aiResponse.targeted_actions)) {
  console.log(`Found ${aiResponse.targeted_actions.length} targeted actions`);

  const sortedActions = aiResponse.targeted_actions.sort((a, b) => 
    (a.execution_order || 999) - (b.execution_order || 999)
  );

  for (const action of sortedActions) {
    console.log(`Validating action: ${action.action} (Risk: ${action.risk_level})`);

    const validation = validateCommand(action.command, action.risk_level);

    if (validation.safe) {
      actionsToExecute.push({
        description: action.action,
        command: action.command,
        target: action.target,
        risk_level: action.risk_level,
        expected_outcome: action.expected_outcome,
        execution_order: action.execution_order || 999,
        justification: action.justification
      });
      console.log(`✅ Action approved: ${action.action}`);
    } else {
      blockedActions.push({
        ...action,
        block_reason: validation.reason
      });
      console.log(`❌ Action blocked: ${action.action} - ${validation.reason}`);
    }
  }
} else {
  console.log("No targeted_actions found in AI response");
}

console.log(`Summary: ${actionsToExecute.length} actions to execute, ${blockedActions.length} blocked`);

// Create execution payload for SSH node
const executionNodes = actionsToExecute.map((action, index) => ({
  json: {
    // SSH configuration for n8n SSH node
    ssh_host: instanceIP,
    ssh_credential: sshCredential,
    ssh_command: action.command,

    // Action metadata
    action_description: action.description,
    target: action.target,
    risk_level: action.risk_level,
    expected_outcome: action.expected_outcome,
    execution_order: action.execution_order,
    justification: action.justification,

    // Execution tracking
    execution_index: index + 1,
    total_actions: actionsToExecute.length,

    // Original context
    instance: alertData.instance,
    alert_name: alertData.alertname,
    ai_assessment: aiResponse.situation_assessment,

    // For Discord reporting
    execution_summary: `Executing ${actionsToExecute.length} targeted actions on ${instanceIP}, ${blockedActions.length} blocked for safety`
  }
}));

// If no actions to execute, return summary with details
if (executionNodes.length === 0) {
  return [{
    json: {
      execution_status: 'NO_SAFE_ACTIONS',
      message: 'No safe actions to execute based on AI recommendations',
      actions_analyzed: aiResponse.targeted_actions?.length || 0,
      blocked_actions: blockedActions,
      ai_assessment: aiResponse.situation_assessment,
      server: instanceIP,
      discord_message: `⚠️ System analysis complete for ${instanceIP}. ${blockedActions.length} actions blocked for safety (${blockedActions.map(a => a.action).join(', ')}). Manual intervention recommended.`
    }
  }];
}

console.log(`Prepared ${executionNodes.length} SSH commands for execution on ${instanceIP}`);
return executionNodes;

